MediaEngine::ParsedSource read(QByteArray bytes, bool database = true)
{
	QBuffer input(&bytes);
	input.open(QIODevice::ReadOnly);
	MediaEngine::Cancellation cancellation;
	return database ? MediaEngine::MdbReader{}.read(input, {{}, cancellation}) : MediaEngine::OmfReader{}.read(input, {{}, cancellation});
}

MediaEngine::Projection project(const MediaEngine::ParsedSource &source)
{
	MediaEngine::Cancellation cancellation;
	return source.snapshot && source.snapshot->source == MetadataSource::Mdb
		? MediaEngine::projectMdb(source, cancellation) : MediaEngine::projectOmf(source, cancellation);
}

MediaEngine::ParsedSource copiedAudioSource(const QByteArray &summary, bool wave, const QByteArray &type = "omfi:VarLenBytes")
{
	TypedBento writer;
	writer.head(1);
	writer.referenceArray(1, "OMFI:ObjectSpine", {101}, 1);
	object(writer, 101, "MOBJ");
	writer.add(101, "OMFI:MOBJ:MobID", "omfi:UID", uid(11));
	writer.add(101, "OMFI:MOBJ:PhysicalMedia", "omfi:ObjRef", writer.reference(201, 1));
	object(writer, 201, wave ? "WAVD" : "AIFD");
	writer.add(201, wave ? "OMFI:WAVD:Summary" : "OMFI:AIFD:Summary", type, summary);
	writer.add(201, "OMFI:MDFL:Length", "omfi:Length64", number<qint64>(96000));
	return read(writer.build());
}

